// Browser-only PDF/download helpers for the AI-visibility report — SPLIT OUT of
// aiAuditReportHtml.ts so that module stays PURE (no document/window) and is importable
// server-side (the Deno edge fn render-audit-report reuses renderReportHtml). These use the
// DOM (offscreen iframe + window.print) and only ever run in the SPA.
import { renderReportHtml, esc, type AiAuditReportData } from './aiAuditReportHtml';
import { buildWelcomePackHtml, type WelcomePackInput } from './welcomePackHtml';

/** "ABLM Associates" + suffix → a clean PDF filename base ("ABLM-Associates-…"). Chrome/Edge
 *  use the document <title> as the default "Save as PDF" filename. */
function pdfTitle(businessName: string, suffix: string): string {
  const base = (businessName || "Business").trim()
    .replace(/[^\w\s-]/g, "").replace(/\s+/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "") || "Business";
  return `${base}-${suffix}`;
}

/** Save a self-contained HTML document as a PDF via the browser's print-to-PDF. Renders the
 *  HTML into an offscreen iframe, sets its <title> (the default "Save as PDF" filename), then
 *  invokes the print dialog. Vector output: the artifact's own @page / @media print / break-
 *  inside CSS carries through, so the SVG header, grade circles and coloured bands stay crisp
 *  and text stays selectable. The iframe is removed after printing (no leaked nodes). */
function printHtmlAsPdf(html: string, title: string): void {
  const titled = html.replace(/<title>[\s\S]*?<\/title>/i, `<title>${esc(title)}</title>`);
  const iframe = document.createElement("iframe");
  iframe.setAttribute("aria-hidden", "true");
  // Off-screen but FULLY RENDERED — a real width so the document lays out at its normal size
  // and paginates correctly. A 0×0 / visibility:hidden / display:none iframe is NOT laid out,
  // so the print engine captures a collapsed render → one near-empty page. Height is grown to
  // the content after load so the whole document is in layout.
  iframe.style.position = "fixed";
  iframe.style.left = "-10000px";
  iframe.style.top = "0";
  iframe.style.width = "794px"; // ~A4 width @96dpi
  iframe.style.height = "1123px"; // ~A4 height; replaced with content height on load
  iframe.style.border = "0";
  iframe.style.opacity = "0"; // hide visually WITHOUT suppressing layout/paint (unlike visibility/display)
  let done = false;
  const cleanup = () => { if (done) return; done = true; iframe.remove(); };
  iframe.onload = () => {
    const win = iframe.contentWindow;
    const doc = iframe.contentDocument;
    if (!win || !doc) { cleanup(); return; }
    try { doc.title = title; } catch { /* same-origin srcdoc */ }
    // Size to content so the FULL document is laid out (not clipped to a viewport height).
    try { iframe.style.height = `${doc.documentElement.scrollHeight}px`; } catch { /* ignore */ }
    win.addEventListener("afterprint", () => setTimeout(cleanup, 300), { once: true });
    setTimeout(cleanup, 60_000); // fallback if afterprint never fires (rare)
    // Print only AFTER layout + paint have settled (double rAF) so nothing prints empty.
    requestAnimationFrame(() => requestAnimationFrame(() => { win.focus(); win.print(); }));
  };
  document.body.appendChild(iframe);
  iframe.srcdoc = titled;
}

/** Save the standalone report as a PDF (print-to-PDF — vector, design-preserving). Prints whichever
 *  version the operator is viewing — the Client/Internal toggle in AiAuditReport sets `d.internal`. */
export function downloadReportHtml(d: AiAuditReportData): void {
  /* ⛔ LAST LINE OF DEFENCE: a snapshot taken while a run was in flight must not become a PDF. The
     preview's button is disabled in that state; this stops a caller that forgets. The rendered
     document would only carry the still-measuring banner anyway, but a banner is not a report. */
  if (d.measuring) {
    console.warn(`[report] refusing to print: still measuring (${d.measuring.runsDone} of ${d.measuring.runsTarget} runs done)`);
    return;
  }
  /* ⛔ CLIENT IS THE DEFAULT, AND THAT DEFAULT IS DEFENSIVE. Winnability is included ONLY when
     `internal` is EXPLICITLY true; an unset/false flag renders the CLIENT document. So a caller that
     forgets to pass a choice can never hand a client a report with the internal notes on it — the
     leak direction fails safe. The operator preview's toggle defaults to Client and resets to Client
     on every report open, so producing the internal PDF is always a conscious two-step choice. */
  printHtmlAsPdf(renderReportHtml({ ...d, internal: d.internal === true }), pdfTitle(d.businessName, "AI-Visibility-Report"));
}

/** Save ANY self-contained branded document (e.g. the printable page plan) as a PDF via the SAME
 *  print-to-PDF path the audit report uses — identical pagination, colours and filename behaviour.
 *  The caller renders the HTML (client or internal view) and this prints exactly what it was given. */
export function downloadHtmlDocAsPdf(html: string, businessName: string, filenameSuffix: string): void {
  printHtmlAsPdf(html, pdfTitle(businessName, filenameSuffix));
}

/* ══ WELCOME PACK ═════════════════════════════════════════════════════════════════════════════
   ONE PDF for a client who has just paid: cover, plan, how it works, get more reviews, then their
   audit report with the selling sections hidden.

   ⛔ SAME PRINT PATH AS EVERY OTHER DOCUMENT — printHtmlAsPdf, the offscreen-iframe helper above.
   No second PDF mechanism, so pagination, vector output and the Save-as-PDF filename behave exactly
   as they do for the audit report and the page plan.
   ⚠️ THE TITLE IS THE FILENAME. Chrome and Edge use the document <title> as the default "Save as
   PDF" name, which is why it is set to the human-readable form rather than run through pdfTitle()'s
   hyphenated slug: the client sees this file's name.
   ⚠️ hidePitch is forced inside buildWelcomePackHtml, not passed here — a caller cannot forget it. */
export function downloadWelcomePack(input: WelcomePackInput): void {
  const name = (input.businessName || 'your business').trim();
  printHtmlAsPdf(buildWelcomePackHtml(input), `Findable Welcome Pack - ${name}`);
}
